// App.js
import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Home from './pages/Home';
import './App.css';

const App = () => {
  const [isAuthorized, setIsAuthorized] = useState(false);

  return (
    <Router>
      <div className="app-container">
        {/* Top section for title, description, and search bar */}
        <header className="app-header">
          <h1>Music Track Search</h1>
          <p>Find similar tracks based on your chosen criteria.</p>
        </header>

        {/* Main content area for search panel and table */}
        <main className="app-main">
          <Routes>
            <Route
              path="/"
              element={<Home isAuthorized={isAuthorized} setIsAuthorized={setIsAuthorized} />}
            />
          </Routes>
        </main>
      </div>
    </Router>
  );
};

export default App;
